const updatePage = `-- name: UpdatePage :one
UPDATE pages
SET slug = $2, title = $3, body_markdown = $4, cover_media_id = $5, is_published = $6, show_in_footer = $7,
    sort_order = $8, meta_title = $9, meta_description = $10, meta_keywords = $11, og_media_id = $12,
    updated_at = now()
WHERE id = $1
RETURNING id, slug, title, body_markdown, cover_media_id, is_published, show_in_footer, sort_order, meta_title, meta_description, meta_keywords, og_media_id, created_at, updated_at
`

type UpdatePageParams struct {
	ID              int64
	Slug            string
	Title           string
	BodyMarkdown    string
	CoverMediaID    *int64
	IsPublished     bool
	ShowInFooter    bool
	SortOrder       int32
	MetaTitle       string
	MetaDescription string
	MetaKeywords    string
	OgMediaID       *int64
}

func (q *Queries) UpdatePage(ctx context.Context, arg UpdatePageParams) (Page, error) {
	row := q.db.QueryRow(ctx, updatePage,
		arg.ID,
		arg.Slug,
		arg.Title,
		arg.BodyMarkdown,
		arg.CoverMediaID,
		arg.IsPublished,
		arg.ShowInFooter,
		arg.SortOrder,
		arg.MetaTitle,
		arg.MetaDescription,
		arg.MetaKeywords,
		arg.OgMediaID,
	)
	var i Page
	err := row.Scan(
		&i.ID,
		&i.Slug,
		&i.Title,
		&i.BodyMarkdown,
		&i.CoverMediaID,
		&i.IsPublished,
		&i.ShowInFooter,
		&i.SortOrder,
		&i.MetaTitle,
		&i.MetaDescription,
		&i.MetaKeywords,
		&i.OgMediaID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
